import type { KnowledgeBase } from "@/modules/knowledge-base/schema";
import { matchMentions } from "@/modules/knowledge-base/mentions";
import { compareStyles, score, type RuleResult, type UserInput } from "@/modules/scoring";
import type { AdvisorResult, AiAdjustment, AiBlock, FinalScore } from "./types";

export interface ResultContext {
  /** Generated by the caller (crypto.randomUUID()) so this module stays pure. */
  id: string;
  /** ISO timestamp from the caller. */
  createdAt: string;
  appVersion: string;
}

/**
 * Final scores = rule score + AI delta, re-sorted with the engine's tie-break. Rounded like the engine so
 * equal totals tie exactly. Bounds on the deltas are enforced by the AI module before they get here.
 */
export function finalScores(rules: RuleResult, adjustments: AiAdjustment[], kb: KnowledgeBase): FinalScore[] {
  const delta = new Map<string, number>();
  for (const a of adjustments) delta.set(a.styleId, (delta.get(a.styleId) ?? 0) + a.delta);
  const simplicity = (id: string) => kb.styles.find((s) => s.id === id)?.scores.simplicity?.value ?? 0;
  return rules.ranked
    .map((s) => {
      const aiDelta = delta.get(s.styleId) ?? 0;
      const final = Math.round(Math.min(100, Math.max(0, s.final + aiDelta)) * 1e6) / 1e6;
      return { styleId: s.styleId, ruleScore: s.final, aiDelta, final, base: s.base };
    })
    .sort((a, b) => compareStyles(a, b, simplicity))
    .map((s, i) => ({
      styleId: s.styleId,
      ruleScore: s.ruleScore,
      aiDelta: s.aiDelta,
      finalScore: s.final,
      rank: i + 1,
    }));
}

function snapshotOf(kb: KnowledgeBase): AdvisorResult["snapshot"] {
  return {
    styles: Object.fromEntries(
      kb.styles.map((s) => [
        s.id,
        {
          name: s.name,
          scores: Object.fromEntries(Object.entries(s.scores).map(([a, v]) => [a, v.value])),
          estimated: Object.entries(s.scores)
            .filter(([, v]) => v.source.kind === "general" && v.source.flagged)
            .map(([a]) => a),
        },
      ]),
    ),
  };
}

/** Builds the full result for an input. Pure: same input, KB and context give the same result. */
export function buildResult(input: UserInput, kb: KnowledgeBase, ctx: ResultContext, ai: AiBlock): AdvisorResult {
  const rules = score(input, kb);
  return {
    id: ctx.id,
    createdAt: ctx.createdAt,
    versions: { app: ctx.appVersion, kb: rules.kbVersion, engine: rules.engineVersion },
    input,
    rules,
    ai,
    final: finalScores(rules, ai.adjustments, kb),
    mentions: matchMentions(input.notes, kb),
    snapshot: snapshotOf(kb),
  };
}

/** Merges an AI block that arrived later into an existing result (the rule part never changes). */
export function withAi(result: AdvisorResult, ai: AiBlock, kb: KnowledgeBase): AdvisorResult {
  const versions = { ...result.versions, prompt: ai.promptVersion };
  return { ...result, versions, ai, final: finalScores(result.rules, ai.adjustments, kb) };
}

/**
 * When the AI's adjustments moved a different style to #1, returns the rule engine's top pick and the new
 * one (UI_UX "AI changed the order" banner). Undefined when the top pick is unchanged.
 */
export function topPickChange(result: AdvisorResult): { ruleTop: string; finalTop: string } | undefined {
  const ruleTop = result.rules.ranked[0]?.styleId;
  const finalTop = result.final[0]?.styleId;
  return ruleTop && finalTop && ruleTop !== finalTop ? { ruleTop, finalTop } : undefined;
}
